DELIVERY_JS = r"""
// Delivery routes deliberately use server state; reviews never imply tested or deployed.
const DL={catalog:null,data:null,detail:null,formOpen:false};
const dlState={not_started:'尚未开始',draft:'产物草稿',running:'智能体运行中',review:'待人工复核',approved:'产物已复核',failed:'运行失败'};
const dlRunState={queued:'排队中',running:'运行中',done:'运行完成',failed:'运行失败',cancelled:'已取消'};
const dlPath=id=>'/api/deliveries/'+encodeURIComponent(id);
const dlHref=(id,stage)=>'#/delivery/'+encodeURIComponent(id)+(stage?'/'+encodeURIComponent(stage):'');
function dlRead(k,fallback){try{return JSON.parse(ls.get(k)||'null')||fallback}catch(e){return fallback}}
function dlWrite(k,v){ls.set(k,JSON.stringify(v))}
function dlPill(state,overall){const label=overall&&state==='draft'?'推进中':overall&&state==='approved'?'全部阶段产物已复核':dlState[state]||state||'尚未开始';return `<span class="dl-state ${h(state)}">${h(label)}</span>`}
function dlError(el,error){if(!el)return;el.hidden=false;el.textContent=error.message||String(error);el.focus()}
function dlBusy(button,on){if(!button)return;button.disabled=on;button.setAttribute('aria-busy',String(on));if(on)button.insertAdjacentHTML('afterbegin','<span class="spin" aria-hidden="true"></span> ');else button.querySelector('.spin')?.remove()}
function dlTitle(title){document.title=title+' · '+S.meta.brand}
function dlLoading(label){$('#main').innerHTML=`<div class="dl" aria-busy="true"><div class="dl-top"><div><h1>${h(label)}</h1><p class="dl-lead">正在读取交付记录…</p></div></div><div class="dl-panel"><div class="dl-skeleton short"></div><div class="dl-skeleton"></div><div class="dl-skeleton"></div></div></div>`}
function dlFailure(title,e,retry){$('#main').innerHTML=`<div class="dl"><h1>${h(title)}</h1><div class="dl-error" role="alert">${h(e.message)}</div><div class="dl-actions" style="margin-top:16px"><button id="dlRetry">重新读取</button><a class="btn" href="#/deliveries">返回交付</a></div></div>`;$('#dlRetry').onclick=retry}
async function vDeliveries(action){
  dlTitle('交付');dlLoading('交付工作台');const scope=S.scope==='*'?'':S.scope;
  try{const [data,catalog]=await Promise.all([get('/api/deliveries'+(scope?'?project='+encodeURIComponent(scope):'')),get('/api/delivery/catalog')]);
    if(!['deliveries'].includes(curView()))return;DL.data=data;DL.catalog=catalog;dlListPaint(action==='new'||!S.projects.length||!!dlRead('tmh.delivery.create',{}).title)}catch(e){dlFailure('交付暂时无法读取',e,()=>vDeliveries(action))}}
function dlListPaint(open){
  const rows=DL.data.deliveries||[];DL.formOpen=!!open;
  $('#main').innerHTML=`<div class="dl" id="dlList"><div class="dl-top"><div><h1>交付工作台</h1><p class="dl-lead">从目标到可用的软件。把研究、设计、开发和验收放在同一条工作流里，让每一步都有可检查的产物。</p></div><div class="dl-actions"><button class="primary" id="dlNew">新建交付</button><button id="dlNewProject">创建新项目</button></div></div>
  <div class="dl-options" aria-label="从工作类型开始"><button data-dl-type="new_product">新产品</button><button data-dl-type="feature">新功能</button><button data-dl-type="research">研究调研</button><button data-dl-type="ux">设计与体验</button><button data-dl-type="security">质量与安全</button><button data-dl-type="release">发布上线</button></div>
  <div id="dlCreate" ${open?'':'hidden'}></div><div class="dl-top" style="margin-bottom:16px"><div><h2>正在推进的交付 <span class="dl-muted">${rows.length}</span></h2><span class="dl-muted">${S.scope==='*'?'全部项目':h(S.scope)} · 状态来自产物、运行和复核记录</span></div><a class="btn" href="#/today">查看今日待办</a></div>
  ${rows.length?`<div class="dl-list">${rows.map(d=>`<a class="dl-row" href="${dlHref(d.id)}"><div><h3>${h(d.title)}</h3><p>${h(d.goal)}</p></div><div class="dl-meta"><span>${h(d.project_name||d.project)}</span><span>${h(d.type_name||d.type)}</span></div><div class="dl-meta">${dlPill(d.state,true)}<span>${h(d.state==='approved'?'全部阶段产物已复核':dlStageName(d.current_stage)||'选择阶段开始')} · ${h(ago(d.updated||d.created))}</span></div><span class="dl-arrow" aria-hidden="true">→</span></a>`).join('')}</div>`:`<div class="dl-empty"><h2>从一项明确的目标开始</h2><p>可以是一个新产品、一项新功能，也可以先研究方案。已有代码、知识库和工单可以继续使用；新项目会建立可运行的 Web 起点。</p><div class="dl-actions"><button id="dlEmptyNew">创建第一项交付</button><button id="dlConnect">连接已有项目</button></div></div>`}
  <div class="dl-line dl-actions"><span class="dl-muted">已有工作</span><a class="btn" href="#/reqs">客户需求</a><a class="btn" href="#/tickets">执行工单</a><a class="btn" href="#/versions">预览与版本</a><a class="btn" href="#/learn">复盘与改进</a></div></div>`;
  const show=(type,newProject)=>{const d=dlRead('tmh.delivery.create',{});if(type)d.type=type;if(newProject)d.project='__new';dlWrite('tmh.delivery.create',d);$('#dlCreate').hidden=false;dlCreatePaint();$('#dlTitle').focus();DL.formOpen=true};
  $('#dlNew').onclick=()=>show();$('#dlNewProject').onclick=()=>show('new_product',true);if($('#dlEmptyNew'))$('#dlEmptyNew').onclick=()=>show();if($('#dlConnect'))$('#dlConnect').onclick=()=>newProject();
  document.querySelectorAll('[data-dl-type]').forEach(b=>b.onclick=()=>show(b.dataset.dlType));if(open)dlCreatePaint()}
function dlStageName(key){if(key&&typeof key==='object')return key.name||key.key;return (DL.catalog?.stages||[]).find(s=>s.key===key)?.name||key||''}
function dlCreatePaint(){
  const d=dlRead('tmh.delivery.create',{}),types=DL.catalog.types||[];const type=types.find(t=>t.key===d.type)||types[0]||{key:'new_product',name:'新产品',stages:[]};
  const project=d.project==='__new'||!S.projects.length?'__new':S.projects.some(p=>p.key===d.project)?d.project:S.scope!=='*'?S.scope:S.proj;
  $('#dlCreate').innerHTML=`<form class="dl-form" id="dlCreateForm"><div class="dl-form-main"><div><h2>新建交付</h2><p class="dl-muted">先写清目标。草稿会保存在当前浏览器，提交失败后仍可继续。</p></div>
  <div><label for="dlTitle">交付名称</label><input id="dlTitle" required maxlength="160" value="${h(d.title||'')}" placeholder="例如：客户服务门户的第一个可用版本"></div>
  <div><label for="dlGoal">目标与完成标准</label><textarea id="dlGoal" required placeholder="谁要使用？解决什么问题？看到什么结果才算完成？">${h(d.goal||'')}</textarea></div>
  <div class="dl-field2"><div><label for="dlType">工作类型</label><select id="dlType">${types.map(t=>`<option value="${h(t.key)}" ${t.key===type.key?'selected':''}>${h(t.name)}</option>`).join('')}</select></div><div><label for="dlProject">所属项目</label><select id="dlProject"><option value="__new" ${project==='__new'?'selected':''}>创建新 Web 项目</option>${S.projects.map(p=>`<option value="${h(p.key)}" ${p.key===project?'selected':''}>${h(p.name)} · ${h(p.key)}</option>`).join('')}</select></div></div>
  <div id="dlProjectFields" ${project==='__new'?'':'hidden'}><div class="dl-field2"><div><label for="dlProjectName">新项目名称</label><input id="dlProjectName" value="${h(d.projectName||'')}" placeholder="客户服务门户"></div><div><label for="dlProjectKey">项目标识</label><input id="dlProjectKey" value="${h(d.projectKey||'')}" pattern="[A-Za-z][A-Za-z0-9]{0,9}" maxlength="10" aria-describedby="dlProjectKeyHelp dlProjectKeyError" placeholder="PORTAL"><div class="dl-help" id="dlProjectKeyHelp">以字母开头，最多 10 位，仅字母和数字（自动转大写）。</div><div class="dl-help" id="dlProjectKeyError" role="alert" style="color:#B42318" hidden></div></div></div><p class="dl-help">建立可运行的 Web 项目并执行初始构建、测试。这里生成的是开发起点，业务功能按交付阶段实现。</p></div>
  <div class="dl-error" id="dlCreateError" role="alert" tabindex="-1" hidden></div><div class="dl-status" id="dlDraftStatus" role="status" aria-live="polite">草稿仅保存在当前浏览器</div><div class="dl-actions"><button class="primary" type="submit" id="dlCreateGo">创建交付</button><button type="button" id="dlCreateClose">收起草稿</button><button type="button" id="dlExisting">连接已有项目</button></div></div><aside class="dl-side"><h3>这项交付会经过</h3><ol id="dlTypeStages"></ol><p>阶段记录保存在项目里。产物可以由你编写，也可以交给智能体生成；每次复核绑定具体版本。</p><p>人工复核、实际运行、代码合并和发布各自留证，不会互相替代。</p></aside></form>`;
  const save=()=>{dlWrite('tmh.delivery.create',{title:$('#dlTitle').value,goal:$('#dlGoal').value,type:$('#dlType').value,project:$('#dlProject').value,projectName:$('#dlProjectName').value,projectKey:$('#dlProjectKey').value});$('#dlDraftStatus').textContent='草稿已保存在当前浏览器'};
  const validateKey=()=>{const field=$('#dlProjectKey'),bad=$('#dlProject').value==='__new'&&field.value&&!/^[A-Za-z][A-Za-z0-9]{0,9}$/.test(field.value),message=bad?'项目标识须以字母开头，最多 10 位，只能包含字母和数字，例如 PORTAL。':'';field.setCustomValidity(message);field.setAttribute('aria-invalid',String(!!bad));$('#dlProjectKeyError').hidden=!bad;$('#dlProjectKeyError').textContent=message};
  const projectFields=()=>{const fresh=$('#dlProject').value==='__new';$('#dlProjectFields').hidden=!fresh;$('#dlProjectName').required=fresh;$('#dlProjectKey').required=fresh;$('#dlProjectName').disabled=!fresh;$('#dlProjectKey').disabled=!fresh;validateKey()};
  const stages=()=>{const selected=types.find(t=>t.key===$('#dlType').value);$('#dlTypeStages').innerHTML=(selected?.stages||[]).map(k=>`<li>${h(dlStageName(k))}</li>`).join('')};
  $('#dlCreateForm').oninput=()=>{save();validateKey()};$('#dlType').onchange=()=>{save();stages()};$('#dlProject').onchange=()=>{save();projectFields()};stages();projectFields();
  $('#dlCreateClose').onclick=()=>{save();$('#dlCreate').hidden=true;$('#dlNew').focus()};$('#dlExisting').onclick=()=>{save();newProject()};
  $('#dlCreateForm').onsubmit=async e=>{e.preventDefault();save();const button=$('#dlCreateGo'),error=$('#dlCreateError');error.hidden=true;dlBusy(button,true);
    try{let project=$('#dlProject').value;const draft=dlRead('tmh.delivery.create',{});if(project==='__new'){$('#dlDraftStatus').textContent='正在创建 Web 项目，并运行初始构建和测试…';const result=await post('/api/projects/bootstrap',{key:draft.projectKey.trim(),name:draft.projectName.trim(),brief:draft.goal,template:'web'});project=result.project.key;dlWrite('tmh.delivery.bootstrap.'+project,result);draft.project=project;dlWrite('tmh.delivery.create',draft);await loadProjects();setProj(project);$('#dlDraftStatus').textContent='项目已建立，正在保存交付目标…'}
      const result=await post('/api/deliveries',{project,type:draft.type,title:draft.title,goal:draft.goal});ls.set('tmh.delivery.create',null);location.hash=dlHref(result.delivery.id)}
    catch(err){dlError(error,err);$('#dlDraftStatus').textContent='未完成创建，草稿已保留。若项目已建立，再试会沿用该项目。';const draft=dlRead('tmh.delivery.create',{});if(draft.project&&draft.project!=='__new'){$('#dlProject').insertAdjacentHTML('beforeend',!Array.from($('#dlProject').options).some(o=>o.value===draft.project)?`<option value="${h(draft.project)}">${h(draft.project)}</option>`:'');$('#dlProject').value=draft.project;projectFields()}}
    finally{dlBusy(button,false)}}}
async function vDelivery(id,stageKey){
  dlLoading('交付详情');try{const detail=await get(dlPath(id));if(curView()!=='delivery')return;DL.detail=detail;DL.catalog=detail.catalog||DL.catalog;dlDetailPaint(detail,stageKey)}catch(e){dlFailure('交付详情暂时无法读取',e,()=>vDelivery(id,stageKey))}}
function dlDetailPaint(detail,stageKey){
  const d=detail.delivery,stages=detail.stages||[],stage=stages.find(s=>s.key===stageKey)||stages.find(s=>s.key===(typeof d.current_stage==='object'?d.current_stage.key:d.current_stage))||stages[0];
  if(!stage){dlFailure('这项交付还没有阶段',new Error('请返回交付列表，选择工作类型重新建立交付。'),()=>vDelivery(d.id));return}
  setProj(d.project);paintSel();dlTitle(d.title+' · '+stage.name);DL.detail=detail;
  $('#main').innerHTML=`<div class="dl" id="dlDetail"><div class="dl-crumb"><a href="#/deliveries">交付</a><span>/</span>${h(d.project_name||d.project)}<span>/</span>${h(d.type_name||d.type)}</div><div class="dl-top"><div><h1>${h(d.title)}</h1><p class="dl-lead">${h(d.goal)}</p><div class="dl-actions">${dlPill(d.state,true)}<span class="dl-muted">产物复核不代表测试通过或已部署</span></div></div><button id="dlRefresh">刷新记录</button></div>${dlBootstrapReceipt(d.project)}
  <div class="dl-note dl-refresh" id="dlUpdate" hidden role="status" aria-live="polite"><span id="dlUpdateText"></span><button id="dlUpdateGo">读取最新记录</button></div>
  <div class="dl-layout"><nav class="dl-stages" aria-label="交付阶段">${stages.map((s,i)=>`<a class="dl-stage" href="${dlHref(d.id,s.key)}" ${s.key===stage.key?'aria-current="page"':''}><span class="dl-stage-number" aria-hidden="true">${i+1}</span><span><b>${h(s.name)}</b><small>${h(dlState[s.state]||s.state)}</small></span></a>`).join('')}</nav><div><article class="dl-panel" id="dlStagePanel">${dlStageBody(d,stage)}</article><div class="dl-line"><h2>继续使用项目里的真实记录</h2><div class="dl-actions">${d.ticket?`<a class="btn" href="#/t/${encodeURIComponent(d.ticket)}">执行工单 ${h(d.ticket)}</a>`:''}<a class="btn" href="#/kb">知识库与研究资料</a><a class="btn" href="#/runs">智能体运行</a><a class="btn" href="#/versions/${encodeURIComponent(d.project)}">预览与版本</a><a class="btn" href="#/learn">复盘与改进</a></div>${d.ticket?'':`<form id="dlLinkForm" class="dl-actions" style="margin-top:16px"><label for="dlLinkTicket" style="margin:0">关联已有执行工单</label><input id="dlLinkTicket" required placeholder="例如 APP-12"><button type="submit" id="dlLinkGo">关联工单</button><span id="dlLinkError" role="alert" tabindex="-1" hidden></span></form>`}<div class="dl-help">版本记录代表代码合并；预览和正式发布需各自的运行与环境证据。</div></div></div></div></div>`;
  const refresh=()=>vDelivery(d.id,stage.key);$('#dlRefresh').onclick=refresh;$('#dlUpdateGo').onclick=refresh;dlStageBind(d,stage);
  if($('#dlLinkForm'))$('#dlLinkForm').onsubmit=e=>{e.preventDefault();dlAct(d,stage,{action:'link_ticket',ticket:$('#dlLinkTicket').value.trim()},$('#dlLinkGo'),$('#dlLinkError'))};
  const signature=JSON.stringify(stages.map(s=>[s.key,s.state,s.runs]));poll(async()=>{if(!$('#dlDetail')||document.hidden)return;try{const fresh=await get(dlPath(d.id));if(!$('#dlUpdate'))return;if(signature!==JSON.stringify(fresh.stages.map(s=>[s.key,s.state,s.runs]))){$('#dlUpdate').hidden=false;$('#dlUpdateText').textContent='运行或产物状态已更新。读取最新记录后可以采集结果；当前输入已保存在浏览器。'}}catch(e){if($('#dlUpdate')){$('#dlUpdate').hidden=false;$('#dlUpdateText').textContent='暂时无法同步最新状态：'+e.message+' 当前内容仍保留。'}}},5000,'page')}
function dlBootstrapReceipt(project){
  const receipt=dlRead('tmh.delivery.bootstrap.'+project,null);if(!receipt)return'';
  const checks=Object.entries(receipt.checks||{}),ok=checks.length&&checks.every(([,c])=>c.exit_code===0),warnings=receipt.warnings||[];
  return `<details class="dl-note dl-editor" style="margin-bottom:20px"><summary>项目创建回执 · ${ok?'初始构建与测试通过':'查看检查结果'}${warnings.length?' · 有待处理事项':''}</summary><p>这是 Web 起点的创建记录，不代表业务需求已完成。回执保留在当前浏览器。</p><p>${receipt.preview_configured?'预览命令已配置，需在预览页面启动后查看运行结果。':'预览尚未配置，可到预览与版本页面处理。'} ${receipt.commit?'初始提交：'+h(receipt.commit):''}</p>${warnings.length?`<div class="dl-error">${warnings.map(x=>h(x)).join('<br>')}</div>`:''}${checks.map(([name,c])=>`<details class="dl-run"><summary>${h(name)} · 退出码 ${h(c.exit_code)}</summary><pre>${h((c.command||[]).join(' '))}\n${h(c.output||'')}</pre></details>`).join('')}<a class="btn" href="#/versions/${encodeURIComponent(project)}">打开预览与版本</a></details>`}
function dlStageBody(d,s){
  const a=s.artifact,review=s.review,agents=(S.meta.agents||[]).filter(a=>a.available),running=(s.runs||[]).some(r=>['queued','running'].includes(r.status)),blocked=s.blocked||[];
  const artifactDraft=dlRead('tmh.delivery.artifact.'+d.id+'.'+s.key,null),body=artifactDraft?artifactDraft.body:a?.body||'';
  const runDraft=dlRead('tmh.delivery.run.'+d.id+'.'+s.key,{}),choices=s.key==='develop'?[['plan','编写实现方案'],['fix','修改代码']]:[['ask','研究与生成产物']],allowed=s.allowed_modes||choices.map(x=>x[0]),modes=choices.filter(x=>allowed.includes(x[0]));
  return `<section class="dl-section"><h2>${h(s.name)} ${dlPill(s.state)}</h2><p class="dl-muted">${h(s.description)}</p>${s.issue?`<div class="dl-note" style="margin-bottom:12px">${h(s.issue)}</div>`:''}${blocked.length?`<div class="dl-note"><b>开始前需要完成</b><ul class="dl-blocked">${blocked.map(x=>`<li>${h(x)}</li>`).join('')}</ul></div>`:''}
  <div class="dl-error" id="dlStageError" role="alert" tabindex="-1" hidden></div></section>
  <section class="dl-section"><h2>阶段产物 ${a?`<span class="dl-muted">版本 ${h(a.version)}</span>`:''}</h2>${a?`<div class="dl-muted" style="margin-bottom:16px">${h(a.by||'')} · ${h(a.created)}${a.source_run?' · 来自运行 #'+h(a.source_run):' · 手动保存'}</div><div class="dl-doc">${md(a.body)}</div>`:`<p class="dl-muted">还没有保存产物。可以运行智能体生成，也可以写下已有研究、方案或验证证据。</p>`}
  <details class="dl-editor" ${!a||artifactDraft?'open':''}><summary>${a?'编辑并保存新版本':'编写阶段产物'}</summary><form id="dlArtifactForm"><label for="dlArtifactTitle">产物标题</label><input class="full" id="dlArtifactTitle" value="${h(artifactDraft?.title||a?.title||s.name)}"><label for="dlArtifactBody" style="margin-top:12px">内容与证据（Markdown）</label><textarea id="dlArtifactBody" required>${h(body)}</textarea><div class="dl-help">保存新版本会使旧的人工复核失效。内容和运行证据应说明实际做了什么、结果及限制。</div><div class="dl-actions"><button type="submit" id="dlSaveArtifact" ${running?'disabled':''}>保存产物</button><span class="dl-status" id="dlArtifactDraft" role="status">${artifactDraft?'已恢复本地草稿':'输入会自动保存在当前浏览器'}</span></div></form></details>${(s.history||[]).length?`<details class="dl-editor"><summary>查看历史产物（${s.history.length} 个版本）</summary>${s.history.map(old=>`<details class="dl-run"><summary>版本 ${h(old.version)} · ${h(old.title)} · ${h(old.created)}</summary><div class="dl-doc">${md(old.body)}</div></details>`).join('')}</details>`:''}</section>
  <section class="dl-section"><h2>运行智能体</h2><p class="dl-muted">实际调用已配置的智能体。完成后采集结果形成产物，再进行人工复核。</p><form id="dlRunForm"><div class="dl-field2"><div><label for="dlRunAgent">执行智能体</label><select class="full" id="dlRunAgent">${agents.length?agents.map(a=>`<option value="${h(a.name)}" ${runDraft.agent===a.name?'selected':''}>${h(a.title||a.name)}</option>`).join(''):'<option value="">尚未配置可用智能体</option>'}</select></div><div><label for="dlRunMode">执行动作</label><select class="full" id="dlRunMode">${modes.length?modes.map(([k,l])=>`<option value="${k}" ${runDraft.mode===k?'selected':''}>${l}</option>`).join(''):'<option value="">等待前置条件</option>'}</select></div></div><label for="dlRunQuestion" style="margin-top:14px">补充要求（可选）</label><textarea id="dlRunQuestion" maxlength="1000" style="min-height:80px" placeholder="补充范围、参考资料、约束或需要验证的场景">${h(runDraft.question||'')}</textarea><div class="dl-actions" style="margin-top:12px"><button ${!a?'class="primary"':''} type="submit" id="dlRunGo" ${!s.can_start||!agents.length||running?'disabled':''}>运行当前阶段</button>${!agents.length?'<a class="btn" href="#/settings">配置智能体</a>':''}<span class="dl-help">${running?'已有运行进行中，请等待结果。':!s.can_start?'先完成上方前置条件。':s.key==='develop'?'先运行方案、采集结果并复核，再选择修改代码。':'本次运行只处理当前阶段，不会自动跳过复核。'}</span></div>${(s.run_blocked||[]).length?`<ul class="dl-blocked">${s.run_blocked.map(x=>`<li>${h(x)}</li>`).join('')}</ul>`:''}</form>
  ${(s.runs||[]).map(r=>`<div class="dl-run"><div class="dl-run-head"><b>运行 #${h(r.id)}</b><span class="dl-state ${r.status==='failed'?'failed':r.status==='running'?'running':''}">${h(dlRunState[r.status]||r.status)}</span><span class="dl-muted">${h(r.mode)} · ${h(r.created||r.started)}</span></div>${r.verification?`<details><summary>查看实际验证记录</summary><p class="dl-help">以下记录保留实际执行命令与结果；构建、测试和其他检查分别以记录为准。</p><pre>${h(JSON.stringify(r.verification,null,2))}</pre></details>`:''}${r.result?`<details><summary>查看完整运行输出</summary><pre>${h(r.result)}</pre></details>`:''}<div class="dl-actions"><button type="button" data-dl-run="${h(r.id)}">查看运行详情</button>${r.status==='done'&&r.exit_code===0&&!r.collected?`<button type="button" data-dl-collect="${h(r.id)}">采集为阶段产物</button>`:r.collected?'<span class="dl-muted">已采集为产物</span>':''}${r.status==='failed'?'<span class="dl-muted">查看失败原因，调整补充要求后重试。失败输出不会作为完成证据。</span>':''}</div></div>`).join('')}</section>
  <section class="dl-section"><h2>人工复核</h2><p class="dl-muted">确认本阶段产物足以支撑下一步。测试、安全、性能与上线结果仍以实际运行及证据为准；复核不会自动执行测试、合并代码或发布。</p>${review?`<div class="dl-note"><b>版本 ${h(review.version)} 已由 ${h(review.by)} 人工复核</b><div>${h(review.created)}</div><div class="dl-doc">${md(review.evidence)}</div></div>`:a?`<form id="dlReviewForm"><label for="dlReviewEvidence">复核依据与保留意见</label><textarea id="dlReviewEvidence" required placeholder="核对了哪些需求、方案或运行结果？哪些结果已有实际证据，哪些仍未验证？">${h(dlRead('tmh.delivery.review.'+d.id+'.'+s.key,{}).evidence||'')}</textarea><label class="dl-check"><input id="dlReviewConfirm" required type="checkbox"><span>我已阅读版本 ${h(a.version)}，确认以上依据可追溯。这只记录人工复核。</span></label><button class="primary" id="dlReviewGo" type="submit" ${s.can_review===false?'disabled':''}>记录版本 ${h(a.version)} 的人工复核</button>${s.can_review===false?`<div class="dl-help">${h((s.review_blocked||s.blocked||[]).join('；')||'先完成前置条件，再进行人工复核。')}</div>`:''}</form>`:'<div class="dl-note">先保存或采集阶段产物，再针对具体版本进行复核。</div>'}</section>`}
function dlStageBind(d,s){
  const key='tmh.delivery.artifact.'+d.id+'.'+s.key,runKey='tmh.delivery.run.'+d.id+'.'+s.key;
  $('#dlArtifactForm').oninput=()=>{dlWrite(key,{title:$('#dlArtifactTitle').value,body:$('#dlArtifactBody').value,version:s.artifact?.version||0});$('#dlArtifactDraft').textContent='草稿已保存在当前浏览器'};
  $('#dlArtifactForm').onsubmit=e=>{e.preventDefault();dlAct(d,s,{action:'save_artifact',stage:s.key,title:$('#dlArtifactTitle').value,body:$('#dlArtifactBody').value},$('#dlSaveArtifact'),$('#dlStageError'),()=>ls.set(key,null))};
  const runSave=()=>dlWrite(runKey,{agent:$('#dlRunAgent').value,mode:$('#dlRunMode').value,question:$('#dlRunQuestion').value});$('#dlRunForm').oninput=runSave;
  $('#dlRunForm').onsubmit=e=>{e.preventDefault();runSave();dlAct(d,s,{action:'start',stage:s.key,agent:$('#dlRunAgent').value,mode:$('#dlRunMode').value,question:$('#dlRunQuestion').value,model:'auto'},$('#dlRunGo'),$('#dlStageError'))};
  document.querySelectorAll('[data-dl-run]').forEach(b=>b.onclick=()=>showRun(+b.dataset.dlRun));
  document.querySelectorAll('[data-dl-collect]').forEach(b=>b.onclick=()=>dlAct(d,s,{action:'collect',stage:s.key,run_id:+b.dataset.dlCollect},b,$('#dlStageError')));
  if($('#dlReviewForm')){$('#dlReviewForm').oninput=()=>dlWrite('tmh.delivery.review.'+d.id+'.'+s.key,{evidence:$('#dlReviewEvidence').value});$('#dlReviewForm').onsubmit=e=>{e.preventDefault();dlAct(d,s,{action:'review_artifact',stage:s.key,version:s.artifact.version,confirm:$('#dlReviewConfirm').checked,evidence:$('#dlReviewEvidence').value},$('#dlReviewGo'),$('#dlStageError'),()=>ls.set('tmh.delivery.review.'+d.id+'.'+s.key,null))}}}
async function dlAct(d,s,body,button,error,done){error.hidden=true;dlBusy(button,true);try{const detail=await post(dlPath(d.id),body);if(done)done();toast(({save_artifact:'阶段产物已保存为新版本',review_artifact:'本版本的人工复核已记录',start:'当前阶段已开始执行',collect:'运行输出已采集为草稿',link_ticket:'执行工单已关联'})[body.action]||'记录已保存',4000);stopPolls('page');if(curView()==='delivery'&&decodeURIComponent((location.hash||'').split('/')[2]||'')===String(d.id))dlDetailPaint(detail,s.key)}catch(e){dlError(error,e)}finally{dlBusy(button,false)}}
"""
